 import type { Provenance } from "./grade.ts";

-export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
-  const raw = trailers.get("Provenance");
-  if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
+export type CommitContext = {
+  trailers: ReadonlyMap<string, string>;
+  isSignatureValid: boolean;
+};
+
+export const provenanceOf = (ctx: CommitContext): Provenance => {
+  const raw = ctx.trailers.get("Provenance");
+
+  // "authored" provenance demands cryptographic proof: no self-asserted claims
+  // will be rendered as instructions to agents. Any commit claiming to be
+  // "authored" without a valid signature is demoted to unknown.
+  if (raw === "authored") {
+    return ctx.isSignatureValid ? "authored" : "unknown";
+  }
+
+  if (raw === "inherited" || raw === "reconstructed") return raw;
   return "unknown";
 };
